window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ab62f2ef91447b8c"]={"versions": [{"id": "FIG-ab62f2ef91447b8c", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB-Kompositions- und Schnittstellendiagramm (SW-C Architecture / Interface Overview) auf Ebene der Application Interfaces (AI).\n</li><li><strong>Funktionaler Zweck:</strong> Festlegung der standardisierten Schnittstellen, Signalflüsse und Software-Komponenten (SW-Cs) für das Klemmen- und Zündungsmanagement (<em>Terminal Clamp Control</em>, z. B. Klemme 15, Klemme R, Klemme 50) im Domänenkontext <em>Body &amp; Comfort</em> gemäß <code>AUTOSAR_CP_EXP_AIBodyAndComfort</code>.\n</li><li><strong>Systemeinordnung:</strong> Zentrale Koordinierungsinstanz zur Steuerung der Fahrzeugenergie- und Betriebsmodi über die Application Layer (VFB). Es verbindet fahrerinitiierte Start-/Schlüssel-Eingaben mit Powertrain-Statusrückmeldungen und Wegfahrsperren-/Interdomain-Schnittstellen (Power Management).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Software-Komponenten (SW-Cs)</h5>\n<ul class=\"fig-list\"><li><strong><code>TerminalClmpCtrlMgr</code> (Terminal Clamp Control Manager):</strong> Zentrale logische Applikationskomponente (Solid Box) zur Auswertung von Einschaltbedingungen, Klemmenzuständen und Anforderung der Klemmenmodi.\n</li><li><strong><code>OperModMgr</code> (Operation Mode Manager):</strong> SW-C zur Koordination übergeordneter Fahrzeugbetriebsmodi (<em>Operating Modes</em>).\n</li><li><strong>Fahrer-Interaktionselemente / Eingabe-Komponenten (Solid / Dashed):</strong>\n<ul class=\"fig-list\"><li><code>CylOfKeyMecl</code> (Solid Box): Mechanischer Zündschlüsselzylinder.\n</li><li><code>SwtPush</code> (Solid Box): Start/Stopp-Taster (Push-Button).\n</li><li><code>PASE</code> (Dashed Box): <em>Passive Start and Entry</em> / Keyless-System (Fahrzeugortung des Schlüssels).\n</li><li><code>Remote Engine Starter</code> (Dashed Box): Telematik- oder Funkschnittstelle für Fernstartanforderungen.\n</li></ul>\n</li><li><strong>Cross-Domain- / Subsystem-Entitäten (Dashed Boxes):</strong>\n<ul class=\"fig-list\"><li><code>Interdomain</code>: Domänenübergreifende Schnittstelle (u. a. Chassis/Powertrain/Body), beinhaltet die logischen Teilsysteme:\n<ul class=\"fig-list\"><li><code>PowerManager</code>: Übergeordnetes Energiemanagement.\n</li><li><code>Powertrain</code>: Antriebsstrang (Motorbetriebsstatus).\n</li></ul>\n</li><li><code>Immobilizer</code>: Wegfahrsperrensystem (Freigabe-/Statusprüfung).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Ports und Datenelemente (Sender-Receiver-Schnittstellen)</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Quell-Komponente &amp; Port</th><th>Signal / Datenelement</th><th>Ziel-Komponente &amp; Port</th><th>Semantik / Datentyp</th></tr></thead><tbody><tr><td><code>CylOfKeyMecl.KeyInsertSt</code></td><td><code>KeyInsertSts1</code></td><td><code>TerminalClmpCtrlMgr.KeyInsertSt</code></td><td>Status Schlüssel gesteckt (<em>Key Inserted</em>)</td></tr><tr><td><code>CylOfKeyMecl.TerminalPosnSt</code></td><td><code>TerminalPosnSts1</code></td><td><code>TerminalClmpCtrlMgr.TerminalPosnSt</code></td><td>Mechanische Schlossstellung (Off, Acc, On, Crank)</td></tr><tr><td><code>SwtPush.SwtStrt</code></td><td><code>SwtStrtSts1</code></td><td><code>TerminalClmpCtrlMgr.SwtStrt</code></td><td>Tasterstatus Start/Stopp-Knopf</td></tr><tr><td><code>PASE.LocnOfPaseKeyIs</code></td><td><code>TrsmPosn1</code></td><td><code>TerminalClmpCtrlMgr.LocnOfPaseKeyIs</code></td><td>Lokalisierung des Funkschlüssels (Innenraum/Außenbereich)</td></tr><tr><td><code>Remote Engine Starter.EngStrtRem</code></td><td><code>EngStrtRemReq1</code></td><td><code>TerminalClmpCtrlMgr.EngStrtRem</code></td><td>Fernstart-Anforderung</td></tr><tr><td><code>Interdomain.CluPedlRat</code></td><td><code>CluPedlRat1</code></td><td><code>TerminalClmpCtrlMgr.CluPedlRat</code></td><td>Kupplungspedalposition/-verhältnis (<em>Clutch Pedal Ratio</em>)</td></tr><tr><td><code>Interdomain.TrsmNrGearAct</code></td><td><code>TrsmNrGearAct1</code></td><td><code>TerminalClmpCtrlMgr.TrsmNrGearAct</code></td><td>Aktuelle Gangstufe Getriebe (Neutral/P-Stellung)</td></tr><tr><td><code>Interdomain.BrkPedlPsd</code></td><td><code>BrkPedlPsd1</code></td><td><code>TerminalClmpCtrlMgr.BrkPedlPsd</code></td><td>Bremspedal betätigt (<em>Brake Pedal Pressed</em>)</td></tr><tr><td><code>TerminalClmpCtrlMgr.TerminalClmpMod</code></td><td>(Direktverbindung)</td><td><code>Immobilizer.TerminalClmpMod</code></td><td>Klemmenmodus zur Wegfahrsperren-Aktivierung/-Freigabe</td></tr><tr><td><code>TerminalClmpCtrlMgr.TerminalClmpMod</code></td><td><code>TerminalClmpModReq1</code></td><td><code>Interdomain.TerminalClmpMod</code></td><td>Modusanforderung an das Bordnetz-/Leistungsrelais-Management</td></tr><tr><td><code>Interdomain.PwrSply</code></td><td><code>PwrSplySts1</code></td><td><code>TerminalClmpCtrlMgr.PwrSply</code> &amp; <code>OperModMgr.PwrSply</code></td><td>Bordnetzversorgungsstatus (<em>Power Supply Status</em>)</td></tr><tr><td><code>Interdomain.PtFlgEngRun</code></td><td><code>PtFlgEngRun1</code></td><td><code>TerminalClmpCtrlMgr.PtFlgEngRun</code> &amp; <code>OperModMgr.PtFlgEngRun</code></td><td>Powertrain-Statusflag: Verbrennungsmotor/Antrieb läuft</td></tr><tr><td><code>OperModMgr.OperMod</code></td><td><code>OperModSts1</code></td><td><code>Interdomain.OperMod</code></td><td>Koordinierter Betriebsmodus an übergeordnete Domänen</td></tr></tbody></table></div>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Signalfluss</h4>\n<ol class=\"fig-list\"><li><strong>Zustandserfassung (Startbedingungen):</strong>\n<ul class=\"fig-list\"><li><em>Mechanischer Pfad:</em> <code>CylOfKeyMecl</code> liefert <code>KeyInsertSts1</code> und <code>TerminalPosnSts1</code>.\n</li><li><em>Elektronischer Pfad:</em> <code>SwtPush</code> liefert Tastimpuls (<code>SwtStrtSts1</code>), flankiert von <code>PASE</code> (<code>TrsmPosn1</code>) zur Verifikation, dass sich der Schlüssel im Fahrzeuginnenraum befindet.\n</li><li><em>Startverriegelungen / Interlocks:</em> <code>TerminalClmpCtrlMgr</code> bewertet gleichzeitig <code>BrkPedlPsd1</code> (Automatik), <code>CluPedlRat1</code> (Schaltgetriebe) und <code>TrsmNrGearAct1</code> (P/N-Erkennung).\n</li></ul>\n</li><li><strong>Klemmenwechsel-Arbitrierung:</strong>\n<ul class=\"fig-list\"><li>Der Manager arbitriert die Übergänge (z. B. Standby → Klemme R → Klemme 15 → Start/Klemme 50).\n</li><li>Bei gültigen Bedingungen wird <code>TerminalClmpModReq1</code> an <code>Interdomain</code> und synchron/asynchron der Klemmenstatus an <code>Immobilizer</code> signalisiert.\n</li></ul>\n</li><li><strong>Status-Feedback &amp; Modushaltung:</strong>\n<ul class=\"fig-list\"><li><code>Interdomain</code> (Powertrain/PowerManager) quittiert den Status über <code>PwrSplySts1</code> und meldet via <code>PtFlgEngRun1</code> den erfolgreichen Motorstart.\n</li><li>Diese beiden Signale werden parallel von <code>TerminalClmpCtrlMgr</code> (zur Deaktivierung des Anlassers / Klemme 50) und <code>OperModMgr</code> (zur Umschaltung auf Normalbetriebsmodus <code>OperModSts1</code>) verarbeitet.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Klassifikation &amp; VFB-Mapping:</strong> Alle Verbindungen sind als ungetypte oder nach AUTOSAR-Standard typisierte Sender-Receiver-Interfaces (<code>AUTOSAR_CP_EXP_AIBodyAndComfort</code>) ausgeführt. Bei Rte-Generierung ist auf 1:n-Kommunikation für <code>PwrSplySts1</code> und <code>PtFlgEngRun1</code> zu achten (Fan-Out vom Interdomain-Port auf <code>TerminalClmpCtrlMgr</code> und <code>OperModMgr</code>).\n</li><li><strong>Safety &amp; ASIL-Allokation:</strong> Signale wie <code>BrkPedlPsd1</code>, <code>CluPedlRat1</code> und <code>TrsmNrGearAct1</code> greifen direkt in Startverriegelungen ein; sie erfordern End-to-End-Absicherung (E2E-Profile) bei der Übertragung über CAN/LIN/FlexRay/Ethernet aus der Powertrain-Domäne.\n</li><li><strong>RTE-Vertrag &amp; Timing:</strong> Die Ports des <code>TerminalClmpCtrlMgr</code> zur Taster- und Zündschlosserfassung erfordern typischerweise zyklische Tasks mit kurzer Abtastrate (10–20 ms) oder Event-Triggerung mit Entprell-Logik in den Sensor-Aktuator-SW-Cs.\n</li><li><strong>Interdomain-Abhängigkeit:</strong> <code>Interdomain</code> stellt die Systemgrenze dar (häufig über Gateway und Com/PduR realisiert). Für Software-Integratoren bedeutet dies, dass Signale wie <code>TerminalClmpModReq1</code> und <code>PwrSplySts1</code> mapping-abhängig auf Com-Signale abgebildet werden müssen, falls Powertrain/PowerManager auf separaten ECUs residieren.\n</li></ul>"}, {"id": "FIG-641caa2b35d397c6", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Hardware-Architektur- und Schaltungsschema (Blockschaltbild) im Kontext der AUTOSAR Classic Platform, Dokument AUTOSAR_CP_EXP_AIBodyAndComfort (Kapitel 4.10.2.1). Es illustriert die elektrische Systemtopologie und Schnittstellenverdrahtung für die Subdomäne Terminal Clamp Control (TCC / Klemmensteuerung) im Anwendungsfall eines konventionellen mechanischen Zünd-Anlass-Schlosses mit Zubehörstellung (Mechanical Cylinder with Accessory). Das Schaubild verknüpft fahrzeugseitige Schaltereingänge mit logischen Steuerungsfunktionen (Terminal Clamp Control, Power Management, Starting Control) und elektromechanischen Relaisaktoren zur Energie- und Anlassersteuerung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangssensorik &amp; Schalter:</strong>\n<ul class=\"fig-list\"><li><code>Mechanical Switch</code>: 4-stufiger Drehschalter/Zündschloss (Stellungen: Lock/Off, Accessory, Ignition/On, Start) mit vier diskreten Signalleitungen zur Erfassung des Fahrer-Klemmenwunsches.\n</li><li><code>Gear position P/N</code>: Schalterkontakt gegen Masse zur Rückmeldung der Getriebeposition Parken (<code>P</code>) oder Neutral (<code>N</code>) als Sicherheitsfreigabebedingung.\n</li></ul>\n</li><li><strong>Logische Steuerungsblöcke (SW-C- / ECU-Funktionen):</strong>\n<ul class=\"fig-list\"><li><code>Terminal Clamp Control</code>: Zentraler Klemmenmanager, welcher die Fahreranforderungen erfasst, plausibilisiert und koordinierte Anforderungsbefehle erzeugt.\n</li><li><code>Power Management</code>: Energiemanagement-Einheit zur Ansteuerung der Bordnetzrelais entsprechend den geforderten Klemmenmodi (<code>PwrSplySts1</code>).\n</li><li><code>Starting Control</code>: Anlasser-Steuerungslogik zur Freigabe und Bestromung des Starterrelais.\n</li></ul>\n</li><li><strong>Aktuatorik &amp; Antriebsstrang:</strong>\n<ul class=\"fig-list\"><li><code>Accessory Relay</code>: Elektromechanisches Relais zur Schaltung der Zubehörverbraucher (Klemme 15R / Acc).\n</li><li><code>Ignition Relay1</code> &amp; <code>Ignition Relay2</code>: Redundante bzw. aufgeteilte Zündungsrelais zur Bestromung der Zündungskreise (Klemme 15).\n</li><li><code>Starter Relay</code>: Relais zur Bestromung des Startermotors (Klemme 50).\n</li><li><code>Starter Motor</code>: Elektrischer Anlassermotor, mechanisch gekoppelt an den Verbrennungsmotor (<code>Engine</code>).\n</li><li><code>Engine</code> &amp; <code>ECM</code>: Verbrennungsmotor und Motorsteuergerät (Engine Control Module), welches mit dem Motor zur Drehzahl- und Verbrennungsregelung gekoppelt ist.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der dynamische Ablauf folgt der manuellen Betätigung des mechanischen Zündschlüssels durch den Fahrer:</p>\n<ol class=\"fig-list\"><li><strong>Ruhezustand (Off):</strong> Alle Relais (<code>Accessory Relay</code>, <code>Ignition Relay1/2</code>, <code>Starter Relay</code>) sind abgefallen; die Klemmen sind stromlos.\n</li><li><strong>Stufe Accessory:</strong> Das Schließen des Kontakts für die Zubehörstellung signalisiert an <code>Terminal Clamp Control</code> den Moduswechsel; <code>Power Management</code> bestromt das <code>Accessory Relay</code> (Infotainment/Komfort aktiv).\n</li><li><strong>Stufe Ignition:</strong> Drehen auf Zündung aktiviert die Klemme 15; <code>Power Management</code> schaltet zusätzlich <code>Ignition Relay1</code> und <code>Ignition Relay2</code> ein.\n</li><li><strong>Stufe Start:</strong> Drehen in die federbelastete Taststellung Start erzeugt die Startanforderung. <code>Terminal Clamp Control</code> verifiziert die Sicherheitsbedingung (<code>Gear position P/N</code> geschlossen). Bei erfüllter Freigabe steuert <code>Starting Control</code> das <code>Starter Relay</code> an, welches den <code>Starter Motor</code> bestromt und die <code>Engine</code> andreht. Nach Motorhochlauf und Loslassen des Schlüssels federt der Schalter auf Ignition zurück, und das Anlassrelais fällt ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt als Bestandteil eines AUTOSAR-Explanation-Dokuments (<code>EXP</code>) informativen Charakter und dient als Referenzarchitektur für die Modellierung von AUTOSAR-Software-Komponenten (SW-Cs) und Port-Schnittstellen im Body-&amp;-Comfort-Bereich. Entwickler müssen beachten:</p>\n<ul class=\"fig-list\"><li>Die Anbindung der Schaltersignale erfolgt im realen AUTOSAR-System über I/O-Hardware-Abstraction-SW-Cs oder Sensor-SW-Cs an die standardisierten Schnittstellen (<code>TerminalClmpModReq1</code>, <code>PwrSplySts1</code>).\n</li><li>Die funktionale Aufteilung zwischen <code>Terminal Clamp Control</code>, <code>Power Management</code> und <code>Starting Control</code> kapselt die Arbitrierung des Fahrerwunsches von der konkreten Leistungs- und Relaisansteuerung sowie der motorseitigen Starterlogik.\n</li></ul>"}, {"id": "FIG-36b91e69ec70619f", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) aus AUTOSAR_CP_EXP_AIBodyAndComfort (Kapitel 4.10.2.1). Es spezifiziert das formale Betriebs- und Übergangsverhalten der Klemmensteuerung (<code>TerminalClmpModReq1</code>) für Fahrzeuge mit konventionellem mechanischem Zündschloss und expliziter Zubehörstellung (Mechanical Cylinder with Accessory). Es definiert die logischen Klemmenzustände und deren schlüsselpositionsabhängige Transitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände (States):</strong>\n<ul class=\"fig-list\"><li><code>Off</code>: Klemmenzustand Klemme 0 / Klemme 30 (Ruhemodus, Bordnetz schläft oder befindet sich im Parkzustand).\n</li><li><code>Accessory</code>: Zubehörstufe (Klemme 15R / Acc; Spannungsversorgung für Radio, Infotainment und Nebenverbraucher).\n</li><li><code>IgnitionOn</code>: Zündungsstufe (Klemme 15; alle regulären Steuergeräte und Bordsysteme aktiviert, Fahrbereitschaft oder laufender Motor).\n</li><li><code>Start</code>: Anlasserstufe (Klemme 50; Starteransteuerung zur Aktivierung des Verbrennungsmotors).\n</li></ul>\n</li><li><strong>Trigger, Guards &amp; Signale:</strong>\n<ul class=\"fig-list\"><li><code>KeyPosition</code>: Diskrete Schalterstellung des mechanischen Zylinderkontakts (<code>Off</code>, <code>Accessory</code>, <code>IgnitionOn</code>, <code>Start</code>).\n</li><li><code>Gear position == Parking or Neutral</code>: Sicherheitsbedingung für Automatik- und Schaltgetriebe.\n</li><li><code>Clutch == ON ( in case of MT)</code>: Sicherheits-Guard für Handschaltgetriebe (getretenes Kupplungspedal).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Zustandsmaschine wechselt sequenziell entlang der physischen Drehbewegung des Zündschlüssels:</p>\n<ul class=\"fig-list\"><li><code>Off -&gt; Accessory</code>: Ausgelöst durch Drehbewegung des Schlüssels (<code>KeyPosition: Off -&gt; Accessory</code>).\n</li><li><code>Accessory -&gt; Off</code>: Ausgelöst durch Zurückdrehen des Schlüssels (<code>KeyPosition: Accessory -&gt; Off</code>).\n</li><li><code>Accessory -&gt; IgnitionOn</code>: Ausgelöst durch Weiterdrehen (<code>KeyPosition: Accessory -&gt; Ignition On</code>).\n</li><li><code>IgnitionOn -&gt; Accessory</code>: Ausgelöst durch Zurückdrehen aus der Zündungsstellung (<code>KeyPosition: IgnitionOn -&gt; Accessory</code>).\n</li><li><code>IgnitionOn -&gt; Start</code>: Ausgelöst durch Drehen in die federnde Startposition (<code>KeyPosition: IgnitionOn -&gt; Start</code>), geschützt durch die Verriegelung <code>Gear position == Parking or Neutral &amp;&amp; Clutch == ON ( in case of MT)</code>.\n</li><li><code>Start -&gt; IgnitionOn</code>: Automatischer Rückfall bei Loslassen des federbelasteten Schlüssels (<code>KeyPosition: Start -&gt; IgnitionOn</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informativ/konzeptionell (<code>EXP</code>). Entwickler müssen bei der Implementierung von <code>Terminal Clamp Manager</code> SW-Cs beachten:</p>\n<ul class=\"fig-list\"><li>Die Transition von <code>IgnitionOn</code> nach <code>Start</code> erfordert eine deterministische Auswertung der Verriegelungsbedingungen (Getriebestufe Park/Neutral und getretenes Kupplungspedal bei Handschaltern), um Fehlstarts und ungewollte Fahrzeugbewegungen sicher zu verhindern.\n</li><li>Die Rückkehr aus <code>Start</code> in <code>IgnitionOn</code> wird im mechanischen System direkt durch die Federrückstellung des Zylinders herbeigeführt; die Software muss ein Entprellen der Schaltkontakte sowie eine Wiederholsperre bei bereits laufendem Motor sicherstellen.\n</li></ul>"}, {"id": "FIG-f1de1bf911dc4cc4", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) gemäß AUTOSAR_CP_EXP_AIBodyAndComfort (Kapitel 4.10.2.2). Es modelliert die Klemmenzustandslogik für ein mechanisches Zündschloss ohne separate Zubehörrastung (Mechanical Cylinder without Accessory). In dieser Bauform wird die Zubehörstufe (Accessory) rein über die Schlüsselerkennung (Schlüsselschacht-/Einsteckkontakt) gesteuert, während der Drehbereich nur zwischen Aus, Zündung und Start schaltet.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände (States):</strong>\n<ul class=\"fig-list\"><li><code>Off</code>: Fahrzeugruhezustand (kein Schlüssel gesteckt, Klemmen inaktiv).\n</li><li><code>Accessory</code>: Zubehörstufe (Schlüssel gesteckt; Klemme 15R / Infotainment aktiv).\n</li><li><code>IgnitionOn</code>: Zündung aktiv (Klemme 15 aktiv, Fahrbereitschaft).\n</li><li><code>Start</code>: Anlassphase (Klemme 50 aktiv, Starter bestromt).\n</li></ul>\n</li><li><strong>Trigger &amp; Guards:</strong>\n<ul class=\"fig-list\"><li><code>KeyInsert</code>: Ereignis des physischen Einsteckens des Schlüssels in den Schließzylinder.\n</li><li><code>Remove</code>: Ereignis des vollständigen Abziehens/Entfernens des Schlüssels.\n</li><li><code>KeyPosition: Off -&gt; Ignition On</code>: Schlüsseldrehung aus der mechanischen Nullstellung in die Zündstellung.\n</li><li><code>KeyPosition: IgnitionOn-&gt;Off</code>: Zurückdrehen des Schlüssels in die mechanische Nullstellung (wechselt bei noch gestecktem Schlüssel in <code>Accessory</code>).\n</li><li><code>KeyPosition: IgnitionOn -&gt; Start &amp;&amp; Gear position == Parking or Neutral &amp;&amp; Clutch == ON ( in case of MT)</code>: Sicherheitsüberwachte Anlassanforderung.\n</li><li><code>KeyPosition: Start -&gt; IgnitionOn</code>: Rückfederung des Schlüssels nach Startbetätigung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Einstecken des Schlüssels (<code>KeyInsert</code>) überführt das System unmittelbar von <code>Off</code> nach <code>Accessory</code>.\n</li><li>Drehen des Schlüssels (<code>KeyPosition: Off -&gt; Ignition On</code>) schaltet von <code>Accessory</code> direkt nach <code>IgnitionOn</code>.\n</li><li>Startvorgang (<code>IgnitionOn -&gt; Start</code>): Bei Drehung in die Startstellung und gleichzeitiger Erfüllung der Sicherheitsbedingungen (<code>Gear position == Parking or Neutral &amp;&amp; Clutch == ON</code>) erfolgt der Wechsel nach <code>Start</code>.\n</li><li>Nach dem Loslassen federt der Schlüssel von Start auf Zündung zurück (<code>Start -&gt; IgnitionOn</code>).\n</li><li>Zurückdrehen des Schlüssels auf die mechanische Aus-Position (<code>KeyPosition: IgnitionOn-&gt;Off</code>) führt das System zurück in den Zustand <code>Accessory</code>, da der Schlüssel physisch eingesteckt bleibt.\n</li><li>Erst das physische Abziehen des Schlüssels (<code>Remove</code>) führt den Übergang von <code>Accessory</code> zurück nach <code>Off</code> aus.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informativ (<code>EXP</code>). Wesentliche Implementierungsaspekte:</p>\n<ul class=\"fig-list\"><li>Die Klemmen-Zustandsmaschine unterscheidet sich strukturell von Zündschlössern mit Rastung: Das Signal <code>KeyInsert</code> (bzw. S-Kontakt / Key-In-Sense) steuert das Halten des Zustands <code>Accessory</code>.\n</li><li>Bei Systemauslegung ist zu beachten, dass <code>KeyPosition: IgnitionOn-&gt;Off</code> nicht unmittelbar in den Ruhezustand <code>Off</code>, sondern zurück in <code>Accessory</code> mündet; das Entladen der Batterie durch versehentlich steckengelassene Schlüssel muss durch nachgelagerte Timeout- und Battery-Protection-Logiken im Power Management abgefangen werden.\n</li></ul>"}, {"id": "FIG-6f84597423e41243", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Hardware-Architektur- und Schaltungsschema (Blockschaltbild) im AUTOSAR-Explanation-Dokument AUTOSAR_CP_EXP_AIBodyAndComfort (Kapitel 4.10.2.3). Es beschreibt die Systemkonfiguration und Verdrahtungstopologie für schlüssellose Start-Stopp-Systeme (Push Start System / Keyless Go). Es zeigt den Ersatz des mechanischen Drehschlosses durch einen Starttaster sowie die Integration zusätzlicher sensorischer Freigabepfade (Bremspedalschalter).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangssensorik:</strong>\n<ul class=\"fig-list\"><li><code>Push Switch</code>: Einfacher Taster gegen Masse zur Erfassung von Fahrerbetätigungen (Start/Stop-Impuls) über eine Einzelleitung.\n</li><li><code>Brake Switch</code>: Bremspedalschalter gegen Masse zur sicheren Erfassung des getretenen Bremspedals.\n</li><li><code>Gear position P/N</code>: Schalterkontakt gegen Masse zur Rückmeldung der Wählhebelposition Parken oder Neutral.\n</li></ul>\n</li><li><strong>Logische Steuerungsblöcke:</strong>\n<ul class=\"fig-list\"><li><code>Terminal Clamp Control</code>: Zentraler SW-C-Funktionsblock, der Tastimpulse arbitriert und unter Berücksichtigung von Brems-, Getriebe- und Transponderstatus Klemmenanforderungen steuert.\n</li><li><code>Power Management</code>: Klemmen- und Energiemanager, der die Klemmenrelais <code>Accessory Relay</code>, <code>Ignition Relay1</code> und <code>Ignition Relay2</code> ansteuert.\n</li><li><code>Starting Control</code>: Steuerlogik für das Anlassen des Verbrennungsmotors.\n</li></ul>\n</li><li><strong>Aktuatorik &amp; Antrieb:</strong>\n<ul class=\"fig-list\"><li><code>Accessory Relay</code>, <code>Ignition Relay1</code>, <code>Ignition Relay2</code>: Relaisschaltstufen für Zubehör und Zündung.\n</li><li><code>Starter Relay</code>: Relais zur Bestromung des <code>Starter Motor</code> (Gleichstrommotor).\n</li><li><code>Engine</code> &amp; <code>ECM</code>: Verbrennungsmotor und Motorsteuergerät mit Drehzahlerfassung und Motorbetriebsüberwachung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Tastendruck ohne Bremse (<code>Brake Switch</code> offen):</strong> <code>Terminal Clamp Control</code> schaltet das System zyklisch durch die Klemmenmodi (Off -&gt; Accessory -&gt; IgnitionOn -&gt; Off), indem <code>Power Management</code> die entsprechenden Relais ansteuert (<code>Accessory Relay</code>, <code>Ignition Relay1/2</code>). Ein Motorstart unterbleibt.\n</li><li><strong>Tastendruck mit Bremse (<code>Brake Switch</code> geschlossen) und Wählhebel in <code>P</code> oder <code>N</code>:</strong> <code>Terminal Clamp Control</code> erkennt die Startabsicht und übermittelt Startkommandos an <code>Starting Control</code>.\n</li><li><code>Starting Control</code> erregt das <code>Starter Relay</code>, welches den <code>Starter Motor</code> bestromt. Der Starter spurt ein und dreht die <code>Engine</code> durch.\n</li><li>Nach erfolgreichem Hochlauf meldet das <code>ECM</code> den stabilen Motorlauf zurück, woraufhin die Startanforderung zurückgenommen wird und das System im Zustand IgnitionOn verbleibt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informativ (<code>EXP</code>). Für die AUTOSAR-SW-C-Architektur gilt:</p>\n<ul class=\"fig-list\"><li>Die Steuerung wechselt von einer statischen Mehrstellungsschalterauswertung zu einer impuls- und flankengetriggerten Zustandslogik.\n</li><li>Im Gegensatz zur rein mechanischen Verriegelung bei konventionellen Zündschlössern liegt die Sicherheitsverantwortung (z. B. Ausschluss eines unbeabsichtigten Startereingriffs bei Fahrt) vollständig in der Software-Logik von <code>Terminal Clamp Control</code> und <code>Starting Control</code>.\n</li><li>Für sicherheitsrelevante Funktionen müssen Eingangssignale wie <code>Brake Switch</code> redundant oder plausibilisiert eingelesen werden.\n</li></ul>"}, {"id": "FIG-aecf103f4137eb17", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) gemäß AUTOSAR_CP_EXP_AIBodyAndComfort (Kapitel 4.10.2.3). Es spezifiziert die formale Zustandslogik für das tastengesteuerte Start-Stopp-System (Push Start System). Es definiert die Übergänge zwischen den Klemmenmodi in Abhängigkeit von Tasterbetätigung, Transponderposition im Fahrzeuginnenraum, Bremspedalzustand, Getriebestellung und Motorlaufstatus (<code>PtFlgEngRun1</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände (States):</strong>\n<ul class=\"fig-list\"><li><code>Off</code>: Ruhezustand (Fahrzeug ausgeschaltet, Klemmen inaktiv).\n</li><li><code>Accessory</code>: Zubehörstufe (Infotainment aktiv).\n</li><li><code>IgnitionOn</code>: Zündung aktiv bzw. regulärer Fahrbetrieb.\n</li><li><code>Start</code>: Anlasserphase (Startermotor aktiv).\n</li></ul>\n</li><li><strong>Trigger- &amp; Zustandssignale (Guards):</strong>\n<ul class=\"fig-list\"><li><code>Pushing</code>: Tasterbetätigung (Start-Stopp-Knopf gedrückt).\n</li><li><code>TransmitterPosition</code>: Position des Funkschlüssels/Transponders (<code>inside</code> = autorisierter Schlüssel im Fahrzeuginnenraum erkannt).\n</li><li><code>Brake</code>: Status des Bremspedals (<code>On</code> = getreten, <code>OFF</code> = unbetätigt).\n</li><li><code>Gear Position</code>: Getriebestufe (<code>Parking or Neutral</code>).\n</li><li><code>PtFlgEngRun1</code>: Boolean-Flag des Antriebsstrangs/ECM (<code>true</code> = Motor läuft, <code>false</code> = Motor steht).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Schlüsselschutz:</strong> Bei <code>Pushing &amp;&amp; TransmitterPosition != inside</code> verbleibt das System im Zustand <code>Off</code> (Selbstschleife; Diebstahlschutz).\n</li><li><strong>Zyklisches Durchschalten (ohne Startfreigabe, <code>PtFlgEngRun1 == false</code>):</strong>\n<ul class=\"fig-list\"><li><code>Off -&gt; Accessory</code>: Betätigung bei <code>TransmitterPosition == inside</code>, aber ohne Startbedingung (<code>Brake == OFF || Gear Position != (Parking or Neutral)</code>).\n</li><li><code>Accessory -&gt; IgnitionOn</code>: Erneuter Tastendruck ohne Bremse/P-N.\n</li><li><code>IgnitionOn -&gt; Off</code>: Weiterer Tastendruck ohne Startbedingung schaltet zurück nach <code>Off</code>.\n</li></ul>\n</li><li><strong>Direktstart:</strong>\n<ul class=\"fig-list\"><li><code>Off -&gt; Start</code>, <code>Accessory -&gt; Start</code> sowie <code>IgnitionOn -&gt; Start</code>: Ausgelöst durch <code>(Pushing &amp;&amp; TransmitterPosition == inside) &amp;&amp; (Gear Position == Parking or Neutral) &amp;&amp; (Brake == On) &amp;&amp; (PtFlgEngRun1 == false)</code>.\n</li></ul>\n</li><li><strong>Motorlauf &amp; Motor-Stopp:</strong>\n<ul class=\"fig-list\"><li><code>Start -&gt; IgnitionOn</code>: Automatischer Übergang bei erfolgreichem Motorstart, signalisiert durch <code>PtFlgEngRun1 == true</code>.\n</li><li><code>IgnitionOn -&gt; Off</code>: Motorstopp-Anforderung durch Tastendruck bei laufendem Motor und Getriebeposition P/N (<code>Pushing &amp;&amp; TransmitterPosition == inside &amp;&amp; Gear Position == Parking or Neutral &amp;&amp; PtFlgEngRun1 == true</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informativ (<code>EXP</code>). Wesentliche Implementierungsvorgaben für den <code>Terminal Clamp Manager</code>:</p>\n<ul class=\"fig-list\"><li>Die Zustandsmaschine implementiert die schlüssellose Klemmenfolgesteuerung nach Automotive-Standards. Entwickler müssen die logische Verknüpfung der Guards strikt beachten: Ein Motorstart darf ausschließlich bei positivem Schlüssel-Innenraum-Nachweis (<code>TransmitterPosition == inside</code>), getretenem Bremspedal und Wählhebel in P/N erfolgen.\n</li><li>Das Flag <code>PtFlgEngRun1</code> dient als essenzielles Kriterium zur Unterscheidung zwischen Startanforderung (bei stehendem Motor) und Stoppanforderung (bei laufendem Motor) auf demselben Tasterereignis (<code>Pushing</code>).\n</li></ul>"}, {"id": "FIG-932e81a501395461", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Funktionales Blockschaltbild und Signalflussdiagramm im AUTOSAR-Explanation-Dokument AUTOSAR_CP_EXP_AIBodyAndComfort (Kapitel 4.10.2.4). Es veranschaulicht die Systemarchitektur für den ferngesteuerten Motorstart (Remote Engine Start System). Es visualisiert den Signal- und Befehlspfad von der drahtlosen Funkfernbedienung über das bordeigene Empfangs- und Verarbeitungsmodul bis hin zur Klemmensteuerung (<code>Terminal Clamp Control</code> / TCC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Komponenten:</strong>\n<ul class=\"fig-list\"><li><code>Handheld Remote Key / Fob</code>: Drahtloser Fahrzeugschlüssel mit integrierter Antenne sowie diskreten Bedientasten <code>Start</code> und <code>Stop</code>.\n</li><li><code>Vehicle Antenna</code> &amp; <code>Remote Engine Start</code>: Bordeigenes Hochfrequenz-Empfangsmodul mit Antenne zur Entgegennahme, Demodulation und Authentifizierung der Funksignale.\n</li><li><code>TCC (Terminal Clamp Control)</code>: Zentrales Steuerungsmodul für Klemmen- und Startfunktionen im Fahrzeug.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Signale:</strong>\n<ul class=\"fig-list\"><li>Drahtlose Funkschnittstelle (gestrichelter Pfeil): Übertragung von <code>Start/Stop</code>-Befehlen über RF-Signal an die Fahrzeugantenne.\n</li><li>Bordeigene Schnittstelle (durchgezogener Pfeil): Übertragung des aufbereiteten und sicherheitsüberprüften Befehls <code>Start/Stop</code> von <code>Remote Engine Start</code> an <code>TCC</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Nutzer drückt die Taste <code>Start</code> auf der Fernbedienung; das Funksignal wird drahtlos übermittelt.\n</li><li>Das Modul <code>Remote Engine Start</code> empfängt den Befehl und führt umfassende Authentifizierungs-, Diebstahlschutz- und Sicherheitsprüfungen durch (z. B. Fahrzeug verriegelt, Motorhaube geschlossen, Getriebe in Parkstellung, kein Insasse detektiert).\n</li><li>Sind alle Sicherheitskriterien erfüllt, übermittelt <code>Remote Engine Start</code> die Anforderung <code>Start</code> an <code>TCC</code>.\n</li><li><code>TCC</code> leitet den Motorstart über die nachgelagerte Startsteuerung ein.\n</li><li>Das Beenden des Fernstartmodus erfolgt:\n<ul class=\"fig-list\"><li><strong>Manuell:</strong> durch Drücken der Taste <code>Stop</code> auf dem Schlüssel (Übermittlung des Stop-Signals an <code>TCC</code>).\n</li><li><strong>Automatisch:</strong> durch Ablauf eines systemdefinierten Maximalzeitgebers (Timeout) oder bei Eintritt eines sicherheitskritischen Ereignisses (z. B. unerwartete Fahrzeugentriegelung, Türöffnung, Tritt auf das Bremspedal ohne autorisierten Schlüssel im Innenraum).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informativ (<code>EXP</code>). Architekturanforderungen für AUTOSAR-Entwickler:</p>\n<ul class=\"fig-list\"><li>Die Anforderung aus <code>Remote Engine Start</code> muss in <code>TCC</code> als externe, nicht-fahrerunmittelbare Anforderung behandelt werden (<code>TerminalClmpModReq1</code>), welche strengeren Sicherheits- und Diebstahlrestriktionen unterliegt als der manuelle Start.\n</li><li>Die Kommunikation zwischen Fernbedienung, Remote Engine Start SW-C und TCC erfordert kryptografische Absicherung (Anti-Replay, Challenge-Response) und muss eng mit dem <code>Immobilizer</code> (Wegfahrsperre) und der <code>PaSE</code>-SW-C (Passive Start and Entry) synchronisiert sein.\n</li></ul>"}, {"id": "FIG-0964332e9f5bce51", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) im Kontext der AUTOSAR Classic Platform Spezifikation „Explanation of Application Interfaces - Body and Comfort“ (AUTOSAR_CP_EXP_AIBodyAndComfort). Das Diagramm spezifiziert die Zustands- und Übergangslogik der Klemmensteuerung (Terminal Clamp Control, TCC) für die funktionale Betriebsart des ferngesteuerten Motorstarts (Remote Engine Start).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zustände (States):</p>\n<ul class=\"fig-list\"><li><code>Off</code>: Inaktiver Grundzustand der Klemmen- und Motorsteuerung.\n</li><li><code>Start</code>: Aktive Start- bzw. Anlasserphase zur Initiierung des Motorhochlaufs.\n</li><li><code>IgnitionOn</code>: Zündung aktiv (Klemme 15 aktiv) bei laufendem Verbrennungsmotor im Remote-Betrieb.\n</li></ul>\n<p class=\"fig-p\">Signale, Variablen und Wächterbedingungen (Guards):</p>\n<ul class=\"fig-list\"><li><code>EngStrtRemReq1</code>: Eingangssignal/Request des Remote-Engine-Start-Systems mit den Zuständen <code>Start</code> und <code>Stop</code>.\n</li><li><code>Gear Position</code>: Getriebewahlhebel-/Schaltpositionsindikator (relevante Werte: <code>Parking</code>, <code>Neutral</code>).\n</li><li><code>Brake</code>: Status des Bremssystems bzw. Bremspedals (<code>Off</code>, <code>On</code>).\n</li><li><code>PtFlgEngRun1</code>: Boolean-Statusflag des Antriebsstrangs (Powertrain Flag Engine Run, <code>true</code>/<code>false</code>) zur Signalisierung des aktiven Motorlaufs.\n</li><li><code>Timeout</code>: Zeitüberwachungs-Event für die maximal zulässige Betriebsdauer im Remote-Start-Modus.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Zustandsübergänge und Auswertelogik:</p>\n<ol class=\"fig-list\"><li>Übergang <code>Off</code> -&gt; <code>Start</code>:\n Triggert, wenn alle folgenden Bedingungen zeitgleich erfüllt sind:\n<ul class=\"fig-list\"><li>Fernstartanforderung liegt an: <code>EngStrtRemReq1 == Start</code>\n</li><li>Getriebestellung ist sicher: <code>Gear Position == (Parking or Neutral)</code>\n</li><li>Bremspedal ist unbetätigt: <code>Brake == Off</code>\n</li><li>Motor läuft noch nicht: <code>PtFlgEngRun1 == false</code>\n</li></ul>\n</li><li>Übergang <code>Start</code> -&gt; <code>IgnitionOn</code>:\n Triggert, sobald der Antriebsstrang den erfolgreichen Motorhochlauf meldet:\n<ul class=\"fig-list\"><li><code>PtFlgEngRun1 == true</code>\n</li></ul>\n</li><li>Übergang <code>IgnitionOn</code> -&gt; <code>Off</code>:\n Rückfall in den Ruhezustand (Motorstopp), sobald mindestens eine der Abbruchbedingungen eintritt (OR-Verknüpfung):\n<ul class=\"fig-list\"><li>Fernstopp-Anforderung: <code>EngStrtRemReq1 == Stop</code>\n</li><li>Ablauf der Laufzeitbegrenzung: <code>Timeout</code>\n</li><li>Einlegen einer Fahrstufe: <code>Gear Position != (Parking or Neutral)</code>\n</li><li>Betätigung der Betriebsbremse: <code>Brake == On</code>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Als Teil eines erläuternden Dokuments (<code>EXP</code>) dient die Zustandsmaschine als Referenzentwurf für die Implementierung der Anwendungslogik in Software-Components (SW-Cs) der Karosserieelektronik (z. B. Body Control Module / BCM oder dediziertes TCC-Modul). Entwickler-Hinweise:</p>\n<ul class=\"fig-list\"><li>Die Übergangsbedingungen stellen sicherheitsrelevante Interlocks dar; insbesondere verhindert <code>PtFlgEngRun1 == false</code> das Einspuren des Starters in einen bereits drehenden Motor.\n</li><li>Die Abbruchbedingungen in <code>IgnitionOn</code> erzwingen das sofortige Abschalten des Motors bei unberechtigtem oder unbeabsichtigtem Eingriff (z. B. Tritt auf die Bremse oder Gangwechsel ohne autorisierten Schlüssel im Fahrzeuginnenraum).\n</li><li>Auf AUTOSAR-Ebene sind die Signale <code>EngStrtRemReq1</code> und <code>PtFlgEngRun1</code> über standardisierte Sender-Receiver-Kommunikationsports zwischen den beteiligten SW-Cs (Remote Start, Powertrain Coordinator, TCC) anzubinden.\n</li></ul>"}, {"id": "FIG-d332d0914fb93bf4", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Funktionales Block- und Wirkflussschaubild im Dokument AUTOSAR_CP_EXP_AIBodyAndComfort. Das Diagramm stellt die Topologie und den Signalfluss der Remote-Engine-Start-Funktionskette dar – von der externen Benutzereingabe über die Funkempfangseinheit bis hin zur Klemmensteuerung (Terminal Clamp Control, TCC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Entitäten und Komponenten:</p>\n<ul class=\"fig-list\"><li>Funkschlüssel (Key Fob / Handheld Transmitter): Externes Bediengerät mit zwei Tastern für <code>Start</code> und <code>Stop</code>.\n</li><li>RF-Antenne: Fahrzeugseitige Empfangsantenne für Funksignale.\n</li><li><code>Remote Engine Start</code>: Funktionale Empfangs- und Auswertekomponente (Software-Component bzw. Steuergerätefunktion) zur Validierung und Signalverarbeitung von Fernstartanfragen.\n</li><li><code>TCC</code>: Terminal Clamp Control (Klemmensteuerungs-SW-C), zuständig für die Verwaltung und Schaltung der Klemmenzustände.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungen:</p>\n<ul class=\"fig-list\"><li>Drahtlose Schnittstelle (gestrichelte Wirkungslinie): HF-Signalübertragung des Befehls <code>Start/Stop</code> vom Funkschlüssel zur Antenne.\n</li><li>Steuerschnittstelle (durchgezogene Wirkungslinie): Signalübertragung des standardisierten Steuerbefehls <code>Start/Stop</code> von <code>Remote Engine Start</code> an <code>TCC</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Funktions- und Sequenzablauf:</p>\n<ol class=\"fig-list\"><li>Befehlsauslösung: Der Bediener betätigt am Funkschlüssel die Taste <code>Start</code> oder <code>Stop</code>.\n</li><li>Funkübertragung: Das Bediengerät moduliert und sendet das Signal drahtlos an die Fahrzeugantenne (<code>Start/Stop</code>).\n</li><li>Signalvorverarbeitung: Die Antenne leitet das Signal an den Funktionsblock <code>Remote Engine Start</code> weiter; hier erfolgen Signaldecodierung, Plausibilisierung und Sicherheitsüberprüfungen.\n</li><li>Ansteuerung der Klemmensteuerung: <code>Remote Engine Start</code> leitet den validierten Befehl <code>Start/Stop</code> an die Komponente <code>TCC</code> weiter, welche daraufhin die entsprechenden Klemmenzustandswechsel (z. B. Ansteuerung Klemme 15 / Klemme 50) initiiert.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das architektonische Prinzip der Kapselung funk- und sicherheitsspezifischer Funktionen gegenüber der Klemmensteuerung in AUTOSAR-Systemen. Entwickler-Hinweise:</p>\n<ul class=\"fig-list\"><li>Die Entkopplung über den Block <code>Remote Engine Start</code> stellt sicher, dass kryptografische Verifikation, Wegfahrsperren-/Transponderauthentifizierung und HF-spezifische Protokolle nicht in der Klemmensteuerung (<code>TCC</code>) implementiert werden müssen.\n</li><li>Die Schnittstelle zwischen <code>Remote Engine Start</code> und <code>TCC</code> korrespondiert mit einem AUTOSAR-Sender-Receiver- oder Client-Server-Interface (Bereitstellung des Signals <code>EngStrtRemReq1</code>).\n</li><li><code>TCC</code> führt keine eigenständige HF-Signalverarbeitung durch, sondern reagiert ausschließlich auf die von <code>Remote Engine Start</code> übergebenen, bereits authentifizierten Kommandos.\n</li></ul>"}], "trans": []};
